const insightsRes = $('Meta API - Read Ad Insights').first().json || {};
const adsetsRes = $input.first().json || {};

const rows = Array.isArray(insightsRes.data) ? insightsRes.data : [];
const adsets = Array.isArray(adsetsRes.data) ? adsetsRes.data : [];
const activeAdsets = adsets.filter(a => a.status === 'ACTIVE' || a.effective_status === 'ACTIVE');

const num = (v) => {
  const p = Number(v);
  return Number.isFinite(p) ? p : 0;
};

const actionVal = (actions, matcher) => {
  if (!Array.isArray(actions)) return 0;
  const match = actions.find(a => matcher(String(a.action_type || '').toLowerCase()));
  return num(match?.value);
};

let totalSpend = 0;
let totalImpressions = 0;
let totalReach = 0;
let totalClicks = 0;
let totalPurchases = 0;
let totalPurchaseValue = 0;

for (const r of rows) {
  totalSpend += num(r.spend);
  totalImpressions += num(r.impressions);
  totalReach += num(r.reach);
  totalClicks += num(r.clicks);
  totalPurchases += actionVal(r.actions, t => t === 'purchase' || t.endsWith('.purchase') || t === 'omni_purchase');
  totalPurchaseValue += actionVal(r.action_values, t => t === 'purchase' || t.endsWith('.purchase') || t === 'omni_purchase');
}

const ctr = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0;
const cpc = totalClicks > 0 ? totalSpend / totalClicks : 0;
const roas = totalSpend > 0 ? totalPurchaseValue / totalSpend : 0;
const cpp = totalPurchases > 0 ? totalSpend / totalPurchases : 0;

const hasSpend = totalSpend > 0;
const isZeroConversionAlert = totalSpend >= 1000 && totalPurchases === 0;

return [{
  json: {
    account_id: 'act_2598854173902437',
    account_name: 'Cevonne ad a/c',
    has_spend: hasSpend,
    is_zero_conversion_alert: isZeroConversionAlert,
    total_spend: totalSpend,
    total_purchases: totalPurchases,
    total_revenue: totalPurchaseValue,
    roas: roas,
    cpp: cpp,
    impressions: totalImpressions,
    reach: totalReach,
    clicks: totalClicks,
    ctr: ctr,
    cpc: cpc,
    active_adsets_count: activeAdsets.length,
    active_adset_names: activeAdsets.map(a => a.name).slice(0, 3),
    date_label: 'Yesterday'
  }
}];

