const agg = $('Code - Aggregate Ad Metrics').first().json;
const aiRes = $input.first().json;

let aiDecision = 'MAINTAIN';
let aiSummary = 'Daily ad delivery is active within target parameters.';
let aiAction = 'Monitor ROAS trends and maintain active budget allocation.';

try {
  const content = aiRes.choices?.[0]?.message?.content;
  if (content) {
    const parsed = JSON.parse(content);
    if (parsed.decision) aiDecision = parsed.decision.toUpperCase();
    if (parsed.summary) aiSummary = parsed.summary;
    if (parsed.action) aiAction = parsed.action;
  }
} catch (e) {}

const spendFormatted = agg.total_spend.toLocaleString('en-IN', { maximumFractionDigits: 2 });
const revFormatted = agg.total_revenue.toLocaleString('en-IN', { maximumFractionDigits: 2 });
const roasFormatted = agg.roas.toFixed(2);
const cppFormatted = agg.cpp > 0 ? `₹${agg.cpp.toFixed(2)}` : 'N/A (0 Purchases)';
const cpcFormatted = agg.cpc.toFixed(2);
const ctrFormatted = agg.ctr.toFixed(2);

let warningBanner = '';
if (agg.is_zero_conversion_alert) {
  warningBanner = `\n⚠️ *CRITICAL ALERT:* Ad spend exceeded ₹1,000 with 0 purchases recorded yesterday. Review product landing page & checkout flow immediately!\n`;
}

const message = `📈 *CEVONNE META ADS DAILY PERFORMANCE*\n` +
  `📅 *Reporting Period:* Yesterday\n` +
  warningBanner + `\n` +
  `💵 *Spend & Returns:*\n` +
  `• Total Ad Spend: *₹${spendFormatted}*\n` +
  `• Purchases Tracked: *${agg.total_purchases}*\n` +
  `• Purchase Value: *₹${revFormatted}*\n` +
  `• Return on Ad Spend (ROAS): *${roasFormatted}x*\n` +
  `• Cost Per Purchase (CPP): *${cppFormatted}*\n\n` +
  `📊 *Traffic & Efficiency:*\n` +
  `• Impressions: *${agg.impressions.toLocaleString('en-IN')}*\n` +
  `• Link Clicks: *${agg.clicks.toLocaleString('en-IN')}*\n` +
  `• Click-Through Rate (CTR): *${ctrFormatted}%*\n` +
  `• Cost Per Click (CPC): *₹${cpcFormatted}*\n\n` +
  `🤖 *AI Strategic Advisory (OpenAI):*\n` +
  `• Recommendation: *${aiDecision}*\n` +
  `• Insight: ${aiSummary}\n` +
  `• Action: ${aiAction}\n\n` +
  `⚡ *Account Health:* Active (${agg.account_name})\n\n` +
  `Have a high-growth and profitable day ahead! 🚀`;

return [{
  json: {
    has_spend: true,
    report_message: message,
    metrics: agg,
    ai_advisory: { decision: aiDecision, summary: aiSummary, action: aiAction }
  }
}];

